/* Общая оболочка, навигация и доступность сайта. */

    *,
    *::before,
    *::after {
      box-sizing: border-box;
    }

    html {
      min-height: 100%;
    }

    body {
      min-height: 100vh;
      margin: 0;
      background: #ffffff;
      color: #111827;
      font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Arial,
        sans-serif;
    }

    img,
    svg,
    canvas {
      max-width: 100%;
    }


  /* Shared learner navigation; all selectors are isolated from lesson CSS. */
  .ms-site-header, .ms-site-footer {
    max-width: 1120px; margin: 0 auto; padding: 20px 24px;
    display: flex; justify-content: space-between; align-items: center;
    gap: 20px; flex-wrap: wrap; line-height: 1.5; font-size: 15px;
  }
  .ms-site-header > div, .ms-site-footer .ms-footer-links { display: flex; gap: 20px; flex-wrap: wrap; }
  .ms-site-header a, .ms-site-footer a { color: #1d4ed8; text-decoration: none; }
  .ms-site-header a:hover, .ms-site-footer a:hover { text-decoration: underline; }
  .ms-site-header .ms-site-brand {
    display: inline-flex; align-items: center; gap: 10px;
    min-height: 44px; padding: 4px 0; font-size: 22px;
    font-weight: 650; letter-spacing: -0.025em; color: #172554;
  }
  .ms-site-header .ms-brand-mark { flex: 0 0 32px; color: #2563eb; }
  .ms-site-header .ms-site-brand:hover { color: #1d4ed8; text-decoration: none; }
  .ms-site-header .ms-site-brand:focus-visible, .ms-site-footer a:focus-visible {
    outline: 3px solid #2563eb; outline-offset: 4px; border-radius: 6px;
  }
  .ms-site-header > div a { display: inline-flex; align-items: center; min-height: 44px; }
  .ms-site-footer {
    border-top: 1px solid #dbeafe; border-radius: 16px 16px 0 0;
    margin-top: 32px; padding: 28px 24px; background: #f8fafc; color: #475569;
  }
  .ms-site-footer .ms-footer-identity { flex: 1 1 340px; }
  .ms-site-footer .ms-footer-brand { color: #172554; font-size: 18px; font-weight: 650; }
  .ms-site-footer .ms-footer-identity p { max-width: 510px; margin: 6px 0 0; font-size: 14px; }
  .ms-site-footer .ms-footer-links { align-items: center; gap: 8px 20px; }
  .ms-site-footer .ms-footer-links a { display: inline-flex; align-items: center; min-height: 44px; }
  .ms-support-page a, .ms-card a, .ms-pdf-card a { color: #1d4ed8; text-underline-offset: 3px; }
  .ms-contact-email { font-size: 24px; font-weight: 700; overflow-wrap: anywhere; }
  .ms-support-links { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 20px; }
  .ms-support-links a { padding: 10px 16px; background: #eff6ff; border-radius: 12px; text-decoration: none; }
  .ms-support-links a:hover { background: #dbeafe; }
  .ms-catalogue-links { columns: 2; padding-left: 22px; }
  .ms-catalogue li { padding: 5px 0; break-inside: avoid; }
  .ms-catalogue-section { border-top: 1px solid #dbeafe; padding: 14px 0; }
  .ms-catalogue-section summary { cursor: pointer; color: #1e3a8a; font-weight: 650; }
  .ms-catalogue-section summary span { color: #64748b; font-size: 14px; margin-left: 8px; }
  .ms-catalogue-section ul { padding-left: 24px; }
  .ms-card ul { padding-left: 22px; line-height: 1.7; }
  .ms-card li + li { margin-top: 10px; }
  .ms-pdf-card { max-width: 888px; margin: 24px auto; padding: 24px; border: 1px solid #dbeafe; border-radius: 22px; }
  .ms-pdf-file a {
  display: inline-block;
  margin: 12px 20px 0 0;
}

.ms-pdf-preview {
  width: 100%;
  height: 600px;
}
  body .ms-svg-wrap { max-width: 100%; min-width: 0; overflow-x: auto; }
  body svg.ms-svg { display: block; width: 100%; min-width: 0 !important; height: auto; }
  body .ms-svg-wrap.ms-diagram-expanded > svg.ms-svg { min-width: var(--diagram-width) !important; }
  .ms-diagram-toggle { display: block; margin: 10px 0 0; padding: 8px 12px; border: 1px solid #bfdbfe; border-radius: 10px; background: #eff6ff; color: #1d4ed8; font: inherit; font-size: 14px; cursor: pointer; }
  .ms-diagram-toggle[hidden] { display: none; }
  body h1, body h2, body h3 { overflow-wrap: anywhere; hyphens: auto; }
  body .ms-formula-card { min-width: 0; max-width: 100%; }
  body .ms-formula-card .ms-math-box { max-width: 100%; overflow-x: auto; }
  body .ms-live-table { max-width: 100%; overflow-x: auto; }
  a:focus-visible, summary:focus-visible, button:focus-visible { outline: 3px solid #2563eb; outline-offset: 4px; }
  @media (max-width: 600px) {
    .ms-site-header, .ms-site-footer { padding: 16px; gap: 12px; }
    .ms-site-header > div, .ms-site-footer .ms-footer-links { gap: 14px; }
    .ms-site-header .ms-site-brand { gap: 8px; font-size: 20px; }
    .ms-site-footer { border-radius: 0; padding-top: 24px; padding-bottom: 24px; }
    .ms-catalogue-links { columns: 1; }
    .ms-pdf-card { margin: 20px 12px; padding: 20px; }
    .ms-page > .ms-hero { padding: 28px 22px; }
    .ms-page .ms-title { font-size: 34px; overflow-wrap: anywhere; }
  }

